#include <limits.h>
#include <stddef.h>
#include <stdio.h>

static int add_to_value(int *value, int amount)
{
    if (value == NULL) {
        return 0;
    }
    if ((amount > 0 && *value > INT_MAX - amount) ||
        (amount < 0 && *value < INT_MIN - amount)) {
        return 0;
    }
    *value += amount;
    return 1;
}

static int sum_values(const int values[], size_t count, long long *sum_out)
{
    size_t i;
    long long sum = 0;

    if (sum_out == NULL || (count > 0U && values == NULL)) {
        return 0;
    }
    for (i = 0U; i < count; ++i) {
        if ((values[i] > 0 && sum > LLONG_MAX - (long long)values[i]) ||
            (values[i] < 0 && sum < LLONG_MIN - (long long)values[i])) {
            return 0;
        }
        sum += (long long)values[i];
    }
    *sum_out = sum;
    return 1;
}

int main(void)
{
    int score = 7;
    const int values[] = {4, -2, 9, 0};
    long long total;

    if (!add_to_value(&score, 3) ||
        !sum_values(values, sizeof values / sizeof values[0], &total)) {
        fputs("calculation failed\n", stderr);
        return 1;
    }
    printf("score=%d total=%lld\n", score, total);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

enum Result {
    RESULT_INVALID = 0,
    RESULT_EMPTY = 1,
    RESULT_READY = 2
};

struct Learner {
    const char *name;
    unsigned int mark;
};

struct Report {
    size_t passed;
    unsigned int highest;
    unsigned long long total;
};

static enum Result make_report(const struct Learner learners[], size_t count,
                               struct Report *out)
{
    size_t i;
    struct Report report = {0U, 0U, 0ULL};

    if (out == NULL || (count > 0U && learners == NULL)) {
        return RESULT_INVALID;
    }
    if (count == 0U) {
        *out = report;
        return RESULT_EMPTY;
    }
    for (i = 0U; i < count; ++i) {
        if (learners[i].name == NULL || learners[i].mark > 100U) {
            return RESULT_INVALID;
        }
        report.total += (unsigned long long)learners[i].mark;
        if (learners[i].mark >= 50U) {
            ++report.passed;
        }
        if (i == 0U || learners[i].mark > report.highest) {
            report.highest = learners[i].mark;
        }
    }
    *out = report;
    return RESULT_READY;
}

int main(void)
{
    const struct Learner learners[] = {
        {"Ira", 72U}, {"Noah", 49U}, {"Zoya", 88U}
    };
    const size_t count = sizeof learners / sizeof learners[0];
    struct Report report;
    enum Result result = make_report(learners, count, &report);

    if (result != RESULT_READY) {
        fputs("report unavailable\n", stderr);
        return 1;
    }
    printf("passed=%zu highest=%u total=%llu average=%.2f\n",
           report.passed, report.highest, report.total,
           (double)report.total / (double)count);
    return 0;
}
